def new_board(rows, cols):
    return [[0] * cols for _ in range(rows)]          # fix 1

def record(board, row, col, points, log=None):        # fix 2
    if log is None:
        log = []
    board[row][col] = board[row][col] + points
    log.append((row, col, points))
    return log

def best_row(totals):
    best = 0
